import json


class RestAPI:
    def __init__(self, database=None):
        self.users = {}
        database = database or {}
        for user in database.get("users", []):
            name = user["name"]
            self.users[name] = {
                "name": name,
                "owes": {k: round(float(v), 2) for k, v in (user.get("owes") or {}).items() if v},
                "owed_by": {k: round(float(v), 2) for k, v in (user.get("owed_by") or {}).items() if v},
            }

    # ------------------------------------------------------------------ helpers
    @staticmethod
    def _balance(user):
        total = sum(user["owed_by"].values()) - sum(user["owes"].values())
        return round(total, 2)

    def _serialize(self, user):
        return {
            "name": user["name"],
            "owes": dict(user["owes"]),
            "owed_by": dict(user["owed_by"]),
            "balance": self._balance(user),
        }

    @staticmethod
    def _set_debt(debtors, creditor, other, amount):
        """Record that `debtors[other]` owes `amount` (0 removes the entry)."""
        amount = round(amount, 2)
        if amount == 0:
            debtors.pop(other, None)
        else:
            debtors[other] = amount

    def get(self, url, payload=None):
        if url == "/users":
            names = None
            if payload:
                data = json.loads(payload) if isinstance(payload, str) else payload
                names = data.get("users")
            if names is None:
                selected = sorted(self.users)
            else:
                selected = sorted(n for n in names if n in self.users)
            return json.dumps({"users": [self._serialize(self.users[n]) for n in selected]})
        raise ValueError("Unknown url: {}".format(url))

    def post(self, url, payload=None):
        data = payload
        if isinstance(data, str):
            data = json.loads(data)
        data = data or {}

        if url == "/add":
            name = data["user"]
            self.users[name] = {"name": name, "owes": {}, "owed_by": {}}
            return json.dumps(self._serialize(self.users[name]))

        if url == "/iou":
            lender = data["lender"]
            borrower = data["borrower"]
            amount = round(float(data["amount"]), 2)

            lender_user = self.users[lender]
            borrower_user = self.users[borrower]

            # Existing debt of lender towards borrower is netted out first.
            lender_owes_borrower = lender_user["owes"].get(borrower, 0.0)
            net = round(lender_owes_borrower - amount, 2)

            if net >= 0:
                # lender still owes borrower
                self._set_debt(lender_user["owes"], borrower, borrower, net)
                self._set_debt(borrower_user["owed_by"], lender, lender, net)
            else:
                # borrower now owes lender the difference
                owed = round(-net, 2)
                self._set_debt(borrower_user["owes"], lender, lender, owed)
                self._set_debt(lender_user["owed_by"], borrower, borrower, owed)

            result = [self._serialize(self.users[lender]), self._serialize(self.users[borrower])]
            result.sort(key=lambda u: u["name"])
            return json.dumps({"users": result})

        raise ValueError("Unknown url: {}".format(url))
